/** A first profile, pre-filled with the company details typed at sign-up (country kept only inside the sourcing scope). */
function signupProfile(email:string,signup?:{name:string;country:string;legalForm:string}):SupplierProfile{
 const base=emptyProfile();const country=signup?.country&&isSourcingCountry(signup.country)?signup.country:'';
 return {...base,legalName:signup?.name||'',legalForm:signup?.legalForm||'',country,headquarters:{...base.headquarters,country},contact:{...base.contact,email}};
}
/** Public company fields that differ between the private draft and the published profile. */
function unpublishedCompanyChanges(p:SupplierProfile,pub:Publication|null):[string,string][]{
 if(!pub)return [];const d=pub.public_details||{};const out:[string,string][]=[];const differ=(a:unknown,b:unknown)=>String(a??'').trim()!==String(b??'').trim();
 const list=(v:string)=>v.slice(0,5000);const website=/^https?:\/\/\S+\.\S+/i.test(p.website)?p.website.slice(0,500):'';
 if(differ(p.legalName,pub.display_name))out.push(['Registered name','Raison sociale']);
 if(differ(p.country,pub.country_code)||differ(p.headquarters.city,pub.city))out.push(['Location','Localisation']);
 if(differ(p.description,pub.description)||differ(p.activity,d.activity)||differ(website,d.website||''))out.push(['Presentation','Présentation']);
 if(differ(list(p.capabilities.processes),(pub.processes||[]).join(','))||differ(list(p.capabilities.materials),(pub.materials||[]).join(','))||differ(p.capabilities.equipment,d.equipment)||differ(p.capabilities.quality,d.quality))out.push(['Capabilities','Capacités']);
 if(differ(p.branding?.logoId,d.branding?.logoId)||(p.branding?.coverIds||[]).join()!==(d.branding?.coverIds||[]).join())out.push(['Logo and cover photos','Logo et photos de couverture']);
 const contact=p.contact.publish?[p.contact.name,p.contact.role,p.contact.email,p.contact.phone].join('|'):'';const published=d.referenceContact?[d.referenceContact.name,d.referenceContact.role,d.referenceContact.email,d.referenceContact.phone].join('|'):'';
 if(differ(contact,published)||differ(p.contact.languages,d.languages))out.push(['Reference contact','Contact de référence']);
 return out;
}
